ents/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"Marcin Pietrzak\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:570:\"\n<p class=\"wp-block-paragraph\">Kolejne spotkanie WordUp Warszawa już 28 kwietnia!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Miejsce: <strong>H.4.0.S</strong>, Marszałkowska, Warszawa</p>\n\n\n\n<p class=\"wp-block-paragraph\">Rejestracja: <a href=\"https://app.evenea.pl/event/wordup-waw-7/\">https://app.evenea.pl/event/wordup-waw-7/</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Udział jest bezpłatny</strong>, ale obowiązuje rezerwacja miejsc, a <strong>liczba miejsc jest ograniczona</strong> więc nie trać czasu i łap swój bilet na najbliższy WordUp Warszawa!</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"https://pl.wordpress.org/2026/04/02/wordup-warszawa/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"54399\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:76:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:36:\"WordUp pierwszy raz w Olsztynie 👌\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"https://pl.wordpress.org/2026/03/10/wordup-pierwszy-raz-w-olsztynie/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:76:\"https://pl.wordpress.org/2026/03/10/wordup-pierwszy-raz-w-olsztynie/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 10 Mar 2026 15:45:53 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:10:\"Wydarzenie\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:7:\"Olsztyn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://pl.wordpress.org/?p=54367\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:473:\"Z radością ogłaszamy pierwszą grupę prelegentów WordUp Olsztyn #1, który odbędzie się 28 marca 2026 roku w Olsztynie. Wydarzenie skierowane jest do osób związanych z tworzeniem stron internetowych, WordPressem, marketingiem internetowym oraz szeroko rozumianą branżą digital. W programie zaplanowaliśmy dzień pełen prezentacji, rozmów i spotkań społeczności. Poniżej przedstawiamy prelegentów, którzy pojawią się podczas pierwszej edycji [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Mariusz Szatkowski\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:5271:\"\n<p class=\"wp-block-paragraph\">Z radością ogłaszamy pierwszą grupę prelegentów <strong><a href=\"https://wpolsztyn.pl/#r\" data-type=\"link\" data-id=\"https://wpolsztyn.pl/#r\">WordUp Olsztyn #1</a></strong>, który odbędzie się <strong>28 marca 2026 roku w Olsztynie</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Wydarzenie skierowane jest do osób związanych z tworzeniem stron internetowych, WordPressem, marketingiem internetowym oraz szeroko rozumianą branżą digital. W programie zaplanowaliśmy dzień pełen prezentacji, rozmów i spotkań społeczności.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Poniżej przedstawiamy prelegentów, którzy pojawią się podczas pierwszej edycji WordUp Olsztyn.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Michał Strześniewski</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Mniej wtyczek, więcej sensu – AI Assisted Engineering w praktyce</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Branża developmentu zmienia się bardzo szybko. W tej prezentacji Michał opowie o tym, jak sztuczna inteligencja zmieniła jego sposób pracy z WordPressem i podejście do budowania projektów. Pokaże, jak dzięki wykorzystaniu AI można pracować szybciej, precyzyjniej i z większą kontrolą nad tym, co faktycznie trafia do projektu.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Karolina Tanona</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Szczegóły prezentacji wkrótce.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Marcin Merchel</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Architektura decyzji: jak strony internetowe projektują nasze wybory</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Prezentacja spojrzy na strony internetowe nie tylko jako na produkty technologiczne, ale również jako systemy wpływu. Marcin pokaże, jak architektura informacji, UX, domyślne opcje czy mechanizmy społecznego dowodu słuszności wpływają na decyzje użytkowników.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Wojciech Babicz</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Jak nie dać sobie ukraść 100 000 Euro?</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Prelekcja poświęcona współczesnym zagrożeniom w internecie. Na podstawie realnych przykładów z branży hostingowej Wojciech pokaże, jakie metody wykorzystują dziś cyberprzestępcy oraz jak firmy mogą zabezpieczać się przed utratą pieniędzy i danych.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Magdalena Paciorek</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Szczegóły prezentacji wkrótce.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Mariusz Miś</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Marketer na dopalaczach, który został najlepszym klientem agencji od stron www</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Historia marketera, który wykorzystał nowoczesne narzędzia marketingowe, aby zmienić sposób działania swojego zespołu i poprawić efektywność współpracy z agencjami tworzącymi strony internetowe.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Jakub Jóźwiak</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Szczegóły prezentacji wkrótce.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Bartek Jaskulski</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Jak uratować subskrybenta, który wcale nie chciał odejść?</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Bartek pokaże, jak w sklepach i usługach subskrypcyjnych można odzyskiwać klientów, którzy utracili dostęp przez nieudaną płatność. Na przykładach strategii stosowanych przez największe platformy pokaże, jak wdrożyć w WordPressie skuteczny system ponowień płatności.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Magdalena Magdziarz</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Hello World 2.0: marki IT, które nie brzmią jak dokumentacja</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">O tym, jak marki technologiczne mogą zmienić sposób komunikacji i zacząć mówić do użytkowników językiem ludzi, a nie systemów.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Sebastian Miśniakiewicz</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Organizacja WordCamp Europe w Krakowie</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Prezentacja o kulisach organizacji <strong>WordCamp Europe w Krakowie</strong> – jednej z największych konferencji WordPress na świecie.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Andrzej Sadowski</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Jak przestać poprawiać stronę w nieskończoność</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Dlaczego wiele projektów webowych wpada w spiralę niekończących się poprawek? Andrzej pokaże, jak dzięki strategii, dobrze zaprojektowanej mapie strony i jasno określonym celom biznesowym można skutecznie zakończyć ten proces.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Szczegóły wydarzenia oraz formularz rejestracji dostępne są na stronie: <a href=\"https://wpolsztyn.pl/#r\">https://wpolsztyn.pl/#r</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Udział w wydarzeniu jest <strong>bezpłatny</strong>, jednak <strong>wymagana jest wcześniejsza rejestracja</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Do zobaczenia w Olsztynie!</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:73:\"https://pl.wordpress.org/2026/03/10/wordup-pierwszy-raz-w-olsztynie/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"54367\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:76:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"WordUp Gdynia #24 – wiosna czai się za rogiem 🌱\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:92:\"https://pl.wordpress.org/2026/01/09/wordup-gdynia-24-wiosna-czai-sie-za-rogiem-%f0%9f%8c%b1/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:100:\"https://pl.wordpress.org/2026/01/09/wordup-gdynia-24-wiosna-czai-sie-za-rogiem-%f0%9f%8c%b1/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 09 Jan 2026 07:05:56 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:10:\"Wydarzenie\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:6:\"Gdynia\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://pl.wordpress.org/?p=54290\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:426:\"Zapraszamy na 24. edycję WordUp Gdynia, czyli spotkanie lokalnej społeczności WordPressa, WooCommerce i szeroko pojętego webu. To będzie intensywny, merytoryczny weekend, pełen rozmów, doświadczeń z realnych projektów i networkingu bez spiny. WordUp Gdynia to wydarzenie dla osób, które pracują z WordPressem na co dzień, rozwijają swoje produkty, sklepy, agencje albo po prostu chcą lepiej rozumieć [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Mariusz Szatkowski\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:8808:\"\n<p class=\"wp-block-paragraph\">Zapraszamy na <strong>24. edycję WordUp Gdynia</strong>, czyli spotkanie lokalnej społeczności <strong>WordPressa, WooCommerce i szeroko pojętego webu</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">To będzie intensywny, merytoryczny weekend, pełen rozmów, doświadczeń z realnych projektów i networkingu bez spiny.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordUp Gdynia to wydarzenie dla osób, które <strong>pracują z WordPressem na co dzień</strong>, rozwijają swoje produkty, sklepy, agencje albo po prostu chcą lepiej rozumieć narzędzia, z których korzystają.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\"><strong><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f4c5.png\" alt=\"📅\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> Agenda wydarzenia</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f4cd.png\" alt=\"📍\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> 27.02.2026 (piątek), godz. 19:00</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Bifor – luźne spotkanie integracyjne w <strong>PifPaf</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f4cd.png\" alt=\"📍\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> 28.02.2026 (sobota), godz. 12:00–18:00</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Główna część wydarzenia – <a href=\"//generic-entity?number=0\"><strong>Muzeum Miasta Gdyni</strong></a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f4cd.png\" alt=\"📍\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> 28.02.2026 (sobota), godz. 19:00</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Networking po konferencji – ponownie <strong>PifPaf pub</strong></p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\"><strong><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f3a4.png\" alt=\"🎤\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> Prelegenci i prelekcje</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>(kolejność wystąpień przypadkowa)</em></p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Krzysztof Miotk</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>UX</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Prelekcja o doświadczeniach użytkownika, projektowaniu z myślą o realnych potrzebach i o tym, gdzie UX faktycznie robi różnicę w projektach webowych.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Andrzej Piotrowski</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>WordPress Security – case study</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Prawdziwe przypadki, prawdziwe problemy i realne konsekwencje zaniedbań bezpieczeństwa w projektach WordPressowych.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Damian Ślimak</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Na co wymieniłem WordPressa i dlaczego Ty prawdopodobnie tego nie zrobisz</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Damian pokaże, dlaczego w wybranych projektach porzucił WordPressa na rzecz nowoczesnych, ultraszybkich rozwiązań opartych o Astro i AI. Opowie o automatyzacji, agentach AI i pracy bez bazy danych, ale też trzeźwo wyjaśni, dlaczego dla większości projektów WordPress nadal pozostaje najlepszym wyborem.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Tomasz Palak</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Szczegóły prelekcji zostaną ogłoszone wkrótce.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Nemanja Cimbaljevic</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Szczegóły prelekcji zostaną ogłoszone wkrótce.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Wojciech Babicz</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Szczegóły prelekcji zostaną ogłoszone wkrótce.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Paulina Augustowska</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>3 sposoby na projekty, które wymykają się spod kontroli</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Projekt, który zaczyna się rozjeżdżać, rzadko psuje się nagle. Zwykle sygnały ostrzegawcze pojawiają się wcześniej – tylko łatwo je zignorować.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Paulina pokaże trzy kluczowe obszary, które decydują o tym, czy projekt pozostaje pod kontrolą: dobre ustawienie na starcie, sensowną komunikację i konsekwencję w działaniu. Bez teorii, za to z praktycznymi wskazówkami do zastosowania od razu.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Adam Zieliński</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Playground thing <img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f61b.png\" alt=\"😛\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /></strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Eksperymentalnie, technicznie i z dystansem.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Magdalena Wczesna</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Uprość proces zakupu albo stracisz sprzedaż – jak płatności i checkout wpływają na konwersję</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Na podstawie badań zachowań klientów oraz analiz ponad 7 000 sklepów internetowych Magdalena pokaże, jak drobne zmiany w checkoutach mogą realnie zwiększyć sprzedaż.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Poruszone zostaną m.in.:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>wpływ procesu zakupowego i konfiguracji bramek na konwersję,</li>\n\n\n\n<li>optymalizacja checkoutów WooCommerce,</li>\n\n\n\n<li>najczęstsze błędy sprzedawców,</li>\n\n\n\n<li>embedded payments,</li>\n\n\n\n<li>preferencje płatnicze polskich klientów.</li>\n</ul>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Maja Loncar</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Szczegóły prelekcji zostaną ogłoszone wkrótce.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Mary Czekaj</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Szczegóły prelekcji zostaną ogłoszone wkrótce.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\"><strong><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f465.png\" alt=\"👥\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> Organizatorzy</strong></h2>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Mariusz Szatkowski</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Współorganizator, Gruby Zawiadowca</p>\n\n\n\n<p class=\"wp-block-paragraph\">Od lat związany z WordPressem i społecznością WordUp Gdynia.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Magdalena Magdziarz</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Z krwi i kości Ślązaczka, w pracy szybka i konkretna, prywatnie marzycielka. Szkoleniowiec, copywriterka, specjalistka od social mediów i eventów.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Zawodowo związana z markami Smarthost i Altumhost. Królowa Relacyjności i wielka fanka społeczności WordPress.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Marcin Andrzejewski</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Smooth operator – człowiek, dzięki któremu wszystko działa wtedy, kiedy powinno.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\"><strong><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f39f.png\" alt=\"🎟\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> Wstęp i rejestracja</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Wstęp na wydarzenie jest <strong>bezpłatny</strong>, obowiązuje <strong>rejestracja</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Liczba miejsc jest ograniczona.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/27a1.png\" alt=\"➡\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> Rejestracja: <a href=\"https://wpgdynia.pl/#rejestracja\">https://wpgdynia.pl/#rejestracja</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\n\n\n\n<p class=\"wp-block-paragraph\">Zapraszamy!</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:97:\"https://pl.wordpress.org/2026/01/09/wordup-gdynia-24-wiosna-czai-sie-za-rogiem-%f0%9f%8c%b1/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"54290\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:76:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"Mikołajki z WordPressem w Gdyni\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"https://pl.wordpress.org/2025/10/29/mikolajki-z-wordpressem-w-gdyni/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:76:\"https://pl.wordpress.org/2025/10/29/mikolajki-z-wordpressem-w-gdyni/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 29 Oct 2025 05:51:05 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:10:\"Wydarzenie\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:6:\"Gdynia\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://pl.wordpress.org/?p=54202\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:427:\"Zapraszamy na WordUp Gdynia już 6 grudnia 2025 r. w Muzeum Miasta Gdyni. 10 prelekcji, konkretne case’y, networking i dużo WordPressa/WooCommerce. Wstęp bezpłatny &#8211; wymagana rejestracja: https://wpgdynia.pl/#rejestracja WordUp Gdynia — zapisz się i dołącz do społeczności Ledwo zamknęliśmy WordCamp Gdynia, a czujemy, że tematów wcale nie ubyło. Dlatego spotykamy się ponownie — tym razem w [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Mariusz Szatkowski\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2297:\"\n<p class=\"wp-block-paragraph\">Zapraszamy na WordUp Gdynia już 6 grudnia 2025 r. w Muzeum Miasta Gdyni. 10 prelekcji, konkretne case’y, networking i dużo WordPressa/WooCommerce. Wstęp bezpłatny &#8211; wymagana rejestracja: <a href=\"https://wpgdynia.pl/#rejestracja\">https://wpgdynia.pl/#rejestracja</a></p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\"><strong>WordUp Gdynia — zapisz się i dołącz do społeczności</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Ledwo zamknęliśmy WordCamp Gdynia, a czujemy, że tematów wcale nie ubyło. Dlatego spotykamy się ponownie — tym razem w bardziej kameralnej, merytorycznej formule <strong>WordUp Gdynia</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Kiedy:</strong> sobota, <strong>6 grudnia 2025</strong>, godz. <strong>12:00–18:00</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Gdzie:</strong> <strong>Muzeum Miasta Gdyni</strong>, Foyer</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Wstęp:</strong> bezpłatny (obowiązuje rejestracja)</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Rejestracja:</strong> <a href=\"https://wpgdynia.pl/#rejestracja\">https://wpgdynia.pl/#rejestracja</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Strona wydarzenia:</strong> <a href=\"https://wpgdynia.pl\">https://wpgdynia.pl</a></p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Dla kogo?</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Dla twórców i użytkowników WordPressa: developerów, administratorów, właścicieli sklepów, marketerów, SEO, twórców treści i wszystkich, którzy chcą rozwijać swoje projekty na WordPressie/WooCommerce.</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Co w programie?</strong></h3>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>10 prelekcji</strong> &#8211; praktyczne case studies, dobre praktyki, narzędzia.</li>\n\n\n\n<li><strong>Networking</strong> &#8211; poznaj ludzi z Trójmiasta działających w ekosystemie WP.</li>\n\n\n\n<li><strong>Dyskusje po prezentacjach</strong> &#8211; pogłębiamy tematy rozpoczęte na WordCampie.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Liczba miejsc jest ograniczona. Zarezerwuj miejsce już teraz: <strong>https://wpgdynia.pl/#rejestracja</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Do zobaczenia w Gdyni!</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:73:\"https://pl.wordpress.org/2025/10/29/mikolajki-z-wordpressem-w-gdyni/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"54202\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:76:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:42:\"Jesienne spotkanie WordUP Częstochowa #05\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:77:\"https://pl.wordpress.org/2025/10/03/jesienne-spotkanie-wordup-czestochowa-05/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"https://pl.wordpress.org/2025/10/03/jesienne-spotkanie-wordup-czestochowa-05/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 03 Oct 2025 15:46:23 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:10:\"Wydarzenie\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:12:\"Częstochowa\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://pl.wordpress.org/?p=54169\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:87:\"5 edycja WordUP Częstochowa! Zarejestruj się i bądź z nami 23 października 2025 r.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Szymon Kryczka\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2612:\"\n<p class=\"wp-block-paragraph\">Zarejestruj się i stań się częścią naszej dynamicznie rozwijającej się społeczności WordPressa w Częstochowie. Odkrywaj nowe możliwości, nawiązuj cenne kontakty i poszerzaj swoją wiedzę na temat WordPressa. Niezależnie od tego, czy jesteś początkującym entuzjastą, czy doświadczonym profesjonalistą, WordUp Częstochowa to miejsce dla Ciebie.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f4c5.png\" alt=\"📅\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> <strong>Data:</strong> 23.10.2025 r. <br><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f552.png\" alt=\"🕒\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> <strong>Godzina:</strong> 18:00 <br><strong><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f4cd.png\" alt=\"📍\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /></strong> <strong>Miejsce:</strong> Jagair Bar, Częstochowa<br><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f39f.png\" alt=\"🎟\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> <strong>Bezpłatna rejestracja: </strong><a href=\"http://wordup.czest.pl/rejestracja/\" data-type=\"link\" data-id=\"wordup.czest.pl/rejestracja/\" target=\"_blank\" rel=\"noreferrer noopener\">wordup.czest.pl/rejestracja/</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Czekają nas 3 prelekcje:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Paulina Augustowska</li>\n\n\n\n<li>Marlena Lyka</li>\n\n\n\n<li>Sebatian Miśniakiewicz</li>\n</ul>\n\n\n\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" src=\"https://wordup.czest.pl/wp-content/uploads/2025/06/IMG_9196-scaled.jpg\" alt=\"\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" src=\"https://wordup.czest.pl/wp-content/uploads/2025/06/IMG_9285-scaled.jpg\" alt=\"\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" src=\"https://wordup.czest.pl/wp-content/uploads/2025/06/IMG_9258-scaled.jpg\" alt=\"\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Nie ma co zwlekać!</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Bądź jednym z nas i spotkajmy się 23 października!</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\"><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f39f.png\" alt=\"🎟\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> <strong>Bezpłatna rejestracja: </strong><a href=\"http://wordup.czest.pl/rejestracja/\" data-type=\"link\" data-id=\"wordup.czest.pl/rejestracja/\" target=\"_blank\" rel=\"noreferrer noopener\">wordup.czest.pl/rejestracja/</a></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1: