<a href=\"https://profiles.wordpress.org/valer1e/\">Valérie Galassi</a> · <a href=\"https://profiles.wordpress.org/vanonsopensource/\">Van Ons Open Source</a> · <a href=\"https://profiles.wordpress.org/twvania/\">Vania</a> · <a href=\"https://profiles.wordpress.org/vascobaiao/\">Vasco Daniel Baião</a> · <a href=\"https://profiles.wordpress.org/supernovia/\">Velda</a> · <a href=\"https://profiles.wordpress.org/vgnavada/\">vgnavada</a> · <a href=\"https://profiles.wordpress.org/vietcgi/\">vietcgi</a> · <a href=\"https://profiles.wordpress.org/szepeviktor/\">Viktor Szépe</a> · <a href=\"https://profiles.wordpress.org/vincentbreton/\">Vincent Breton</a> · <a href=\"https://profiles.wordpress.org/vipulgupta003/\">Vipul Gupta</a> · <a href=\"https://profiles.wordpress.org/vishalkakadiya/\">Vishal Kakadiya</a> · <a href=\"https://profiles.wordpress.org/vishitshah/\">Vishit Shah</a> · <a href=\"https://profiles.wordpress.org/vishnuprajapat/\">vishnu prajapat</a> · <a href=\"https://profiles.wordpress.org/vrishabhsk/\">Vrishabh Jasani</a> · <a href=\"https://profiles.wordpress.org/waqassafdar/\">Waqas Safdar</a> · <a href=\"https://profiles.wordpress.org/wooxperto/\">WebCartisan</a> · <a href=\"https://profiles.wordpress.org/webmandesign/\">WebMan Design | Oliver Juhas</a> · <a href=\"https://profiles.wordpress.org/george9/\">webtasky</a> · <a href=\"https://profiles.wordpress.org/gauri87/\">WebTechee</a> · <a href=\"https://profiles.wordpress.org/westonruter/\">Weston Ruter</a> · <a href=\"https://profiles.wordpress.org/wfmattr/\">WFMattR</a> · <a href=\"https://profiles.wordpress.org/skorasaurus/\">Will Skora</a> · <a href=\"https://profiles.wordpress.org/winsleyj/\">WinsleyJ</a> · <a href=\"https://profiles.wordpress.org/wiuempe/\">wiuempe</a> · <a href=\"https://profiles.wordpress.org/wolf45/\">wolf45</a> · <a href=\"https://profiles.wordpress.org/wongjn/\">wongjn</a> · <a href=\"https://profiles.wordpress.org/wpexplorer/\">WPExplorer</a> · <a href=\"https://profiles.wordpress.org/wplmillet/\">wplmillet</a> · <a href=\"https://profiles.wordpress.org/wpsoul/\">wpsoul</a> · <a href=\"https://profiles.wordpress.org/wraithkenny/\">WraithKenny</a> · <a href=\"https://profiles.wordpress.org/x-raym/\">X-Raym</a> · <a href=\"https://profiles.wordpress.org/xate/\">xate</a> · <a href=\"https://profiles.wordpress.org/xavilc/\">xavilc</a> · <a href=\"https://profiles.wordpress.org/xwolf/\">xwolf</a> · <a href=\"https://profiles.wordpress.org/yagniksangani/\">Yagnik Sangani</a> · <a href=\"https://profiles.wordpress.org/yguyon/\">Yannis Guyon</a> · <a href=\"https://profiles.wordpress.org/getsyash/\">Yash B</a> · <a href=\"https://profiles.wordpress.org/yashjawale/\">Yash Jawale</a> · <a href=\"https://profiles.wordpress.org/yogeshbhutkar/\">Yogesh Bhutkar</a> · <a href=\"https://profiles.wordpress.org/fierevere/\">Yui</a> · <a href=\"https://profiles.wordpress.org/yusufmudagal/\">Yusuf Mudagal</a> · <a href=\"https://profiles.wordpress.org/zoe20/\">zoe20</a> · <a href=\"https://profiles.wordpress.org/zunaid321/\">Zunaid Amin</a> · <a href=\"https://profiles.wordpress.org/zuveria/\">zuveria</a> · <a href=\"https://profiles.wordpress.org/lstraczynski/\">Łukasz Strączyński</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Ponad <a href=\"https://translate.wordpress.org/stats/\">70 w pełni przetłumaczonych wersji</a> WordPressa 7.0. Tłumacze społecznościowi ciężko pracują, by kolejne były już w drodze. Dziękujemy wszystkim, którzy pomagają udostępniać WordPressa w ponad 200 językach.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Dziękujemy również <a href=\"https://make.wordpress.org/hosting/test-results/\">ponad 21 firmom hostingowym</a>, które testowały wersje przedpremierowo WordPressa 7.0, pomagając upewnić się, że WordPress i platformy hostingowe są w pełni kompatybilne, wolne od błędów i zoptymalizowane pod kątem najlepszego możliwego doświadczenia użytkownika.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Na koniec, dziękujemy wolontariuszom, którzy współtworzą <a href=\"https://wordpress.org/support/forums/\">fora pomocy</a>, odpowiadając na pytania użytkowników WordPressa z całego świata.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Dołącz</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Udział w WordPressie wykracza daleko poza kodowanie. A poznanie możliwości i zaangażowanie się jest proste. Odkryj zespoły, które wspólnie tworzą <a href=\"https://make.wordpress.org/\">Make WordPress</a>, i skorzystaj z <a href=\"https://make.wordpress.org/contribute/\">tego interaktywnego narzędzia</a>, aby zdecydować, który z nich jest dla Ciebie odpowiedni.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:65:\"https://pl.wordpress.org/2026/05/21/wordpress-7-0-armstrong/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"54441\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:79:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"WordUp Warszawa\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:52:\"https://pl.wordpress.org/2026/04/02/wordup-warszawa/\";s:7:\"attribs\";a:0:{}s:8:\"xml