base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:392:\"📅 26 września 2025, godz. 11:30–15:30 📍 PPNT Gdynia, budynek III – sala kinowa (obok wejścia do Experymentu) Chcesz zacząć przygodę z WordPressem, ale gubisz się w gąszczu tutoriali? Masz pomysł na swoją stronę, ale brakuje Ci kogoś, kto pokaże krok po kroku, jak ją stworzyć? WordPress dla Początkujących to darmowe, praktyczne warsztaty, podczas których [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Mariusz Szatkowski\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:3773:\"\n<p class=\"wp-block-paragraph\"><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f4c5.png\" alt=\"📅\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> <strong>26 września 2025, godz. 11:30–15:30</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\"><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f4cd.png\" alt=\"📍\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> <strong>PPNT Gdynia, budynek III – sala kinowa (obok wejścia do Experymentu)</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Chcesz zacząć przygodę z WordPressem, ale gubisz się w gąszczu tutoriali?</p>\n\n\n\n<p class=\"wp-block-paragraph\">Masz pomysł na swoją stronę, ale brakuje Ci kogoś, kto pokaże krok po kroku, jak ją stworzyć?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>WordPress dla Początkujących</strong> to darmowe, praktyczne warsztaty, podczas których doświadczeni twórcy stron przeprowadzą Cię przez cały proces – od instalacji WordPressa po pierwsze modyfikacje wyglądu i zabezpieczenie witryny.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Wydarzenie jest częścią <strong>WordCamp Gdynia 2025</strong>, ale <strong>nie wymaga zakupu biletu</strong> – wystarczy bezpłatna rejestracja. Jeśli jednak chcesz dołączyć także do głównej konferencji (27–28 września), zachęcamy do kupna biletu.</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Dla kogo?</strong></h3>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Dla osób, które <strong>nigdy wcześniej nie korzystały z WordPressa</strong></li>\n\n\n\n<li>Dla marketerów, freelancerów i wirtualnych asystentek chcących samodzielnie tworzyć i edytować strony</li>\n\n\n\n<li>Dla studentów – jako dodatkowy atut w CV</li>\n\n\n\n<li>Dla każdego, kto chce w prosty i uporządkowany sposób zacząć tworzyć strony internetowe</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Co Cię czeka?</strong></h3>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Instalacja i konfiguracja WordPressa</li>\n\n\n\n<li>Wprowadzenie do edytora blokowego (Gutenberg)</li>\n\n\n\n<li>Różnice między motywami a wtyczkami</li>\n\n\n\n<li>Podstawy bezpieczeństwa i optymalizacji strony</li>\n\n\n\n<li>Wskazówki dotyczące wyboru hostingu</li>\n\n\n\n<li>Najczęstsze błędy początkujących – i jak ich unikać</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>Ważne informacje:</strong></h3>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Wydarzenie jest <strong>bezpłatne</strong>, ale liczba miejsc jest ograniczona – obowiązuje rejestracja.</li>\n\n\n\n<li>Warsztaty przeznaczone są dla <strong>początkujących</strong> – jeśli już tworzysz strony, polecamy Contributor Day.</li>\n\n\n\n<li>Udział w warsztatach nie daje dostępu do pozostałych dni WordCamp Gdynia.</li>\n\n\n\n<li>Mamy specjalne bilety studenckie na główną konferencję w cenie 100 zł.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\"><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f517.png\" alt=\"🔗\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /> <strong><a href=\"https://gdynia.wordcamp.org/2025/bilety/wordpress-dla-poczatkujacych/\">Zapisz się i zarezerwuj miejsce już teraz</a> – zacznij swoją przygodę z WordPressem bez chaosu i frustracji.</strong></p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://pl.wordpress.org/files/2025/08/POST_jestescie_gotowi.png\"><img loading=\"lazy\" decoding=\"async\" width=\"768\" height=\"1024\" src=\"https://pl.wordpress.org/files/2025/08/POST_jestescie_gotowi-768x1024.png\" alt=\"\" class=\"wp-image-45416\" srcset=\"https://pl.wordpress.org/files/2025/08/POST_jestescie_gotowi-768x1024.png 768w, https://pl.wordpress.org/files/2025/08/POST_jestescie_gotowi-225x300.png 225w, https://pl.wordpress.org/files/2025/08/POST_jestescie_gotowi.png 1080w\" sizes=\"auto, (max-width: 768px) 100vw, 768px\" /></a></figure>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:97:\"https://pl.wordpress.org/2025/08/12/wordpress-dla-poczatkujacych-darmowe-wydarzenie-w-gdyni/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"45413\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:4:\"href\";s:30:\"https://pl.wordpress.org/feed/\";s:3:\"rel\";s:4:\"self\";s:4:\"type\";s:19:\"application/rss+xml\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:44:\"http://purl.org/rss/1.0/modul